<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Inertia\Testing\AssertableInertia;
use Modules\SampleReadonly\Models\SampleReadonly;
use Yuan\AdminCore\Testing\ModuleAssertions;

use function Pest\Laravel\get;

// Contoh baca saja (generated by make:module): the AGENTS §8 cases for each declared action.

uses(RefreshDatabase::class);

it('redirects guests to login', function (): void {
    $sampleReadonly = SampleReadonly::factory()->create();

    ModuleAssertions::assertGuestRedirected('get', '/admin/sample-readonly');
    ModuleAssertions::assertGuestRedirected('get', "/admin/sample-readonly/{$sampleReadonly->id}");
});

it('needs the permission of each action', function (): void {
    $sampleReadonly = SampleReadonly::factory()->create();

    ModuleAssertions::assertForbiddenWithout('sample-readonly.view', 'get', '/admin/sample-readonly');
    ModuleAssertions::assertForbiddenWithout('sample-readonly.view', 'get', "/admin/sample-readonly/{$sampleReadonly->id}");

    expect($sampleReadonly->fresh()?->trashed())->toBeFalse();
});

it('lists and shows contoh baca saja records', function (): void {
    $sampleReadonly = SampleReadonly::factory()->create();
    ModuleAssertions::actingAsLevelWith(['sample-readonly.view']);

    AssertableInertia::fromTestResponse(get('/admin/sample-readonly')->assertOk())
        ->component('SampleReadonly::Index')
        ->count('sampleReadonlies.items', 1)
        ->where('sampleReadonlies.items.0.id', $sampleReadonly->id);

    AssertableInertia::fromTestResponse(get("/admin/sample-readonly/{$sampleReadonly->id}")->assertOk())
        ->component('SampleReadonly::Show')
        ->where('sampleReadonly.id', $sampleReadonly->id)
        ->where('breadcrumbs.items.1.label', $sampleReadonly->auditLabel());
});

it('rejects a sort the list does not allow', function (): void {
    ModuleAssertions::actingAsLevelWith(['sample-readonly.view']);

    get('/admin/sample-readonly?sort=lock_version')->assertStatus(400);
});

it('scopes every contoh baca saja query to the signed-in user', function (): void {
    $sampleReadonly = SampleReadonly::factory()->create();
    ModuleAssertions::actingAsLevelWith(['sample-readonly.view']);

    ModuleAssertions::assertScopedToUser(SampleReadonly::class, 'get', '/admin/sample-readonly');
    ModuleAssertions::assertScopedToUser(SampleReadonly::class, 'get', "/admin/sample-readonly/{$sampleReadonly->id}");
});
